# Fix the transform function - pattern_row should be a flat list
def transform(grid):
    R = len(grid)
    if R == 0:
        return []

    output = []

    if R == 1:
        row = grid[0]
        rev_row = row[::-1]
        pattern_row = rev_row + row  # Concatenate as flat list
        for _ in range(3):
            output.append(pattern_row)
    else:
        # For each input row, generate 3 output rows
        for in_row_idx in range(R):
            in_row = grid[in_row_idx]
            rev_in_row = in_row[::-1]

            # Pattern A (uses current row reversed + original)
            pattern_a = rev_in_row + in_row

            # Pattern B (uses next row's reverse + original, wraps around)
            other_idx = (in_row_idx + 1) % R
            other_row = grid[other_idx]
            other_rev = other_row[::-1]
            pattern_b = other_rev + other_row

            # Determine which pattern based on row pattern
            # Pattern: A, B, B, A, A, B for 2 rows (row 0, row 1)
            if R == 2:
                if in_row_idx == 0:
                    pattern_row = pattern_a  # row 0 → pattern from row 1
                elif in_row_idx == 1:
                    pattern_row = pattern_b  # row 1 → pattern from row 0
                pattern_row = pattern_a  # reset to pattern a

                # Pattern cycles: A, B, B, A, A, B
                for pattern_idx in range(3):
                    cycle_pos = (in_row_idx * 3 + pattern_idx) % 6
                    if cycle_pos < 3:  # First 3 rows (A, B, B)
                        if in_row_idx == 0:
                            output.append(pattern_a)
                        else:
                            output.append(pattern_b)
                    else:  # Last 3 rows (A, A, B)
                        if in_row_idx == 0:
                            output.append(pattern_a)
                        else:
                            if pattern_idx == 2:
                                output.append(pattern_b)
                            else:
                                output.append(pattern_a)
            else:
                # General case: for each input row, generate blocks
                # Based on demos, the pattern is cycles of using current row vs next row
                for block_idx in range(3):
                    block_num = block_idx + 1
                    # Block 1: uses pattern from in_row_idx
                    # Block 2: uses pattern from (in_row_idx + 1) % R
                    # Block 3: uses pattern from in_row_idx
                    source_idx = (in_row_idx + block_idx) % R
                    source_row = grid[source_idx]
                    source_rev = source_row[::-1]
                    output.append(source_rev + source_row)

    return output

